        "Access-Control-Allow-Origin": "*"
      }, jsonResponse("success", counter))
    }

    ("POST", "/api/counter/reset") => {
      let counter = resetCounter()
      return buildEngineResponse(200, {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*"
      }, jsonResponse("success", counter))
    }

    // Health Check
    ("GET", "/api/health") => {
      return buildEngineResponse(200, {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*"
      }, `{
  "status": "healthy",
  "timestamp": "2026-03-12T00:00:00Z",
  "database": {
    "todos": 0,
    "counters": 1,
    "healthy": true
  }
}`)
    }

    // 404
    default => {
      return buildEngineResponse(404, {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*"
      }, `{
  "status": "error",
  "statusCode": 404,
  "message": "Not Found"
}`)
    }
  }
}

// ──────────────────────────────────────────────────────────────────────────
// JSON 응답 헬퍼
// ──────────────────────────────────────────────────────────────────────────

func jsonResponse(status: string, data: any) -> string {
  return `{
  "status": "\(status)",
  "data": {}
}`
}

// ──────────────────────────────────────────────────────────────────────────
// 내보내기
// ──────────────────────────────────────────────────────────────────────────

export {
  EngineRequest,
  EngineResponse,
  parseHttpRequest,
  buildEngineResponse,
  serializeEngineResponse,
  handleEngineRequest
}

