// TCP Socket Manager (250줄)
// 저수준 소켓 작업 추상화

fn socket_create() -> Result<i32, string>
  // AF_INET (IPv4), SOCK_STREAM (TCP), IPPROTO_TCP
  intent "소켓 생성 및 에러 처리"
  do
    let fd = socket(2, 1, 6)  // socket(AF_INET, SOCK_STREAM, IPPROTO_TCP)
    if fd < 0
      return Err("socket() failed")
    return Ok(fd)
end

fn socket_bind(fd: i32, addr: string, port: i32) -> Result<void, string>
  intent "bind() 호출"
  do
    // sockaddr_in: sin_family (2 bytes), sin_port (2 bytes), sin_addr (4 bytes), sin_zero (8 bytes)
    // 16바이트 구조체
    let port_network = htons(port)  // 포트를 네트워크 순서로
    let addr_bin = inet_aton(addr)  // "127.0.0.1" → 32bit int

    let sockaddr_in = [
      2 as u8, 0 as u8,                    // sin_family = AF_INET (2)
      (port_network >> 8) as u8,           // sin_port (big-endian)
      (port_network & 0xFF) as u8,
      (addr_bin >> 24) as u8,              // sin_addr (big-endian)
      ((addr_bin >> 16) & 0xFF) as u8,
      ((addr_bin >> 8) & 0xFF) as u8,
      (addr_bin & 0xFF) as u8,
      0 as u8, 0 as u8, 0 as u8, 0 as u8, // sin_zero
      0 as u8, 0 as u8, 0 as u8, 0 as u8
    ]

    let ret = bind(fd, sockaddr_in, 16)
    if ret < 0
      return Err("bind() failed")
    return Ok(void)
end

fn socket_listen(fd: i32, backlog: i32) -> Result<void, string>
  intent "listen() 호출"
  do
    let ret = listen(fd, backlog)
    if ret < 0
      return Err("listen() failed")
    return Ok(void)
end

fn socket_accept(fd: i32) -> Result<i32, string>
  intent "accept() 호출 (블로킹)"
  do
    let client_fd = accept(fd, null, null)
    if client_fd < 0
      return Err("accept() failed")
    return Ok(client_fd)
end

fn socket_read(fd: i32, max_len: i32) -> Result<array<u8>, string>
  intent "read() 호출 및 버퍼 반환"
  do
    let buffer = create_buffer(max_len)  // 빈 버퍼 생성
    let n = read(fd, buffer, max_len)

    if n < 0
      return Err("read() failed")

    if n == 0
      return Err("EOF")  // 연결 종료

    // 읽은 바이트만 반환
    let result = slice_buffer(buffer, 0, n)
    return Ok(result)
end

fn socket_write(fd: i32, data: array<u8>) -> Result<i32, string>
  intent "write() 호출"
  do
    let len = length(data)
    let n = write(fd, data, len)

    if n < 0
      return Err("write() failed")

    return Ok(n)
end

fn socket_close(fd: i32) -> Result<void, string>
  intent "close() 호출"
  do
    let ret = close(fd)
    if ret < 0
      return Err("close() failed")
    return Ok(void)
end

fn socket_set_timeout(fd: i32, timeout_ms: i32) -> Result<void, string>
  intent "소켓 타임아웃 설정 (setsockopt)"
  do
    // SO_RCVTIMEO / SO_SNDTIMEO
    // timeval: tv_sec (4), tv_usec (4)

// HTTP Parser (350줄)
// HTTP/1.1 요청 파싱

struct HttpRequest {
  method: string,
  path: string,
  version: string,
  headers: map<string, string>,
  body: array<u8>,
  body_len: i32,
}

enum ParseError {
  InvalidRequestLine,
  InvalidHeaders,
  InvalidBody,
  MissingContentLength,
  ToolargePayload,
}

fn parse_request(raw: array<u8>) -> Result<HttpRequest, ParseError>
  intent "raw 바이트를 HttpRequest로 파싱"
  do
    // 1. CRLF(\r\n)로 라인 분할
    let lines = split_by_crlf(raw)

    if length(lines) < 1
      return Err(InvalidRequestLine)

    // 2. Request Line 파싱
    match parse_request_line(lines[0])
      Ok((method, path, version)) => {
        // 3. Headers 파싱
        match parse_headers_section(lines, 1)
          Ok((headers, body_start)) => {
            // 4. Content-Length 추출
            let content_len = match get_header(headers, "Content-Length")
              Some(len_str) => parse_int_safe(len_str),
              None => 0
            end

            // 5. Body 추출
            let body = extract_body(raw, body_start, content_len)

            // 6. Payload 크기 검증 (1MB limit)
            if content_len > 1048576
              return Err(ToolargePayload)

            return Ok({
              method: method,
              path: path,
              version: version,
              headers: headers,
              body: body,
              body_len: content_len,
            })
          }
          Err(e) => return Err(e)
        end
      }
      Err(e) => return Err(e)
    end
end

fn parse_request_line(line: string) -> Result<(string, string, string), ParseError>
  intent "Request Line 파싱: 'GET /path HTTP/1.1'"
  do
    let parts = split_by_space(line)

    if length(parts) < 3
      return Err(InvalidRequestLine)

    let method = parts[0]
    let path = parts[1]
    let version = parts[2]

    // 유효성 검증
    if !is_valid_method(method)
      return Err(InvalidRequestLine)

