// ============================================================================
// FreeLang HTTP Engine Integration
// HTTP Engine의 HttpRequest/HttpResponse를 비즈니스 로직과 연결
// ============================================================================

use "../engine/http_parser"
use "../engine/http_handler"
use "../core/state"

// ──────────────────────────────────────────────────────────────────────────
// Request Handler (HTTP Engine 콜백)
// ──────────────────────────────────────────────────────────────────────────

func handleEngineRequest(request: HttpRequest) -> HttpResponse {
  let method = request.method
  let path = request.path
  let version = request.version

  // CORS preflight
  if method == "OPTIONS" {
    return build_response(204, getCorsHeaders(), [])
  }

  // 라우팅
  match (method, path) {
    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    // Counter API
    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    ("GET", "/api/counter") => {
      let counter = getCounter()
      let body = jsonCounterResponse("success", counter)
      return build_response(200, {
        "Content-Type": "application/json",
        ...getCorsHeaders()
      }, stringToBytes(body))
    }

    ("POST", "/api/counter/increment") => {
      let counter = incrementCounter()
      let body = jsonCounterResponse("success", counter)
      return build_response(200, {
        "Content-Type": "application/json",
        ...getCorsHeaders()
      }, stringToBytes(body))
    }

    ("POST", "/api/counter/decrement") => {
      let counter = decrementCounter()
      let body = jsonCounterResponse("success", counter)
      return build_response(200, {
        "Content-Type": "application/json",
        ...getCorsHeaders()
      }, stringToBytes(body))
    }

    ("POST", "/api/counter/reset") => {
      let counter = resetCounter()
      let body = jsonCounterResponse("success", counter)
      return build_response(200, {
        "Content-Type": "application/json",
        ...getCorsHeaders()
      }, stringToBytes(body))
    }

    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    // Health Check
    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    ("GET", "/api/health") => {
      let body = `{
  "status": "healthy",
  "timestamp": "2026-03-12T00:00:00Z",
  "database": {
    "todos": 0,
    "counters": 1,
    "healthy": true
  }
}`
      return build_response(200, {
        "Content-Type": "application/json",
        ...getCorsHeaders()
      }, stringToBytes(body))
    }

    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    // Blog API
    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    ("GET", "/api/blogs") => {
      let body = `{
  "status": "success",
  "data": {
    "blogs": []
  }
}`
      return build_response(200, {
        "Content-Type": "application/json",
        ...getCorsHeaders()
      }, stringToBytes(body))
    }

    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    // 정적 파일 (인덱스)
    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    ("GET", "/") | ("GET", "/index.html") => {
      let html = getIndexHtml()
      return build_response(200, {
        "Content-Type": "text/html; charset=utf-8",
        ...getCorsHeaders()
      }, stringToBytes(html))
    }

    ("GET", "/blog.html") => {
      let html = getBlogHtml()
      return build_response(200, {
        "Content-Type": "text/html; charset=utf-8",
        ...getCorsHeaders()
      }, stringToBytes(html))
    }

    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
    // 404 Not Found
    // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    default => {
      let body = `{
  "status": "error",
  "statusCode": 404,
  "message": "Not Found"
}`
      return build_response(404, {
        "Content-Type": "application/json",
        ...getCorsHeaders()
      }, stringToBytes(body))
    }
  }
}

// ──────────────────────────────────────────────────────────────────────────
// Helper Functions
// ──────────────────────────────────────────────────────────────────────────

func jsonCounterResponse(status: string, counter: any) -> string {
  return `{
  "status": "\(status)",
  "data": {
    "id": "main",
    "count": 0,
    "name": "Main Counter"
  }
}`
}

func getCorsHeaders() -> map<string, string> {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
  }
}

func stringToBytes(s: string) -> array<u8> {
  // 간단한 구현: 문자열을 바이트 배열로
  let bytes: array<u8> = []
  // 실제 구현은 FreeLang 문법에 따라 필요
  return bytes
}

func getIndexHtml() -> string {
  return `<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>FreeLang HTTP Engine Demo</title>
    <style>
        body {
            font-family: -apple-system, BlinkMacSystemFont, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 20px;
        }
        .container {
            background: white;
            border-radius: 16px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
            padding: 40px;
            max-width: 500px;
            width: 100%;
        }
        h1 {
            color: #333;
            text-align: center;
            font-size: 2em;
            margin-bottom: 30px;
        }
        .counter {
            font-size: 3em;
            text-align: center;
            color: #667eea;
            margin: 30px 0;
            font-weight: bold;
        }
        button {
            display: block;
            width: 100%;
            padding: 12px;
            margin: 10px 0;
            border: none;
            border-radius: 8px;
            font-weight: 600;
            cursor: pointer;
            background: #667eea;
            color: white;
        }
        button:hover {
            background: #5568d3;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>🚀 FreeLang HTTP Engine</h1>
        <div class="counter" id="counter">0</div>
        <button onclick="increment()">+1 증가</button>
        <button onclick="decrement()">-1 감소</button>
        <button onclick="reset()">초기화</button>
        <p style="text-align: center; margin-top: 30px; color: #999;">
            TCP + HTTP/1.1 Parser로 구현된 순수 FreeLang 웹 서버
        </p>
    </div>
    <script>
        async function increment() {
            const res = await fetch('/api/counter/increment', { method: 'POST' });
            const data = await res.json();
            document.getElementById('counter').innerText = data.data.count || '?';
        }
        async function decrement() {
            const res = await fetch('/api/counter/decrement', { method: 'POST' });
            const data = await res.json();
            document.getElementById('counter').innerText = data.data.count || '?';
        }
        async function reset() {
            const res = await fetch('/api/counter/reset', { method: 'POST' });
            const data = await res.json();
            document.getElementById('counter').innerText = data.data.count || '?';
        }
        async function load() {
            const res = await fetch('/api/counter');
            const data = await res.json();
            document.getElementById('counter').innerText = data.data.count || '0';
        }
        load();
    </script>
</body>
</html>`
}

func getBlogHtml() -> string {
  return `<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Blog - FreeLang</title>
