            text-align: center;
            margin-bottom: 30px;
        }
        a {
            color: #667eea;
            text-decoration: none;
        }
        a:hover {
            text-decoration: underline;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>📝 FreeLang 블로그</h1>
        <p style="text-align: center; color: #999;">아직 발행된 블로그가 없습니다.</p>
        <div style="text-align: center;">
            <a href="/">← 홈으로</a>
        </div>
    </div>
</body>
